"""Native browser-response imports use real pipes, private queues and generated bytes."""
import hashlib, json, pathlib, sys, tempfile, time, uuid
from BrowserTests import host, request, start, rows, close

def main():
    exe,driver=sys.argv[1:3];checks=0
    with tempfile.TemporaryDirectory(prefix='downshift-import-') as temporary:
        root=pathlib.Path(temporary);p=start(driver,root)
        def command(text):
            p.stdin.write(text+'\n');p.stdin.flush();return json.loads(p.stdout.readline())
        def add(source,name,payload,prefix=None,total=None):
            key=uuid.uuid4().hex;spool=root/(key+'.source');spool.write_bytes(payload)
            accepted=request(exe,'browser-prepare',key=key,url=source,filename=name,total=str(len(payload)),mime='application/octet-stream')
            row=next(r for r in rows(p) if r['id']==accepted['downloadId']);target=pathlib.Path(row['destination'])
            if prefix is not None:pathlib.Path(str(target)+'.part').write_bytes(prefix)
            request(exe,'commit',key=key,browserTransport=True,prompt=False)
            request(exe,'browser-update',key=key,file=str(spool),complete=True,total=str(len(payload) if total is None else total),received=str(len(payload)))
            return key,row['id'],spool,target
        def finished(identifier,status=3):
            end=time.monotonic()+15
            while time.monotonic()<end:
                row=next(r for r in rows(p) if r['id']==identifier)
                if row['status'] in (3,4):assert row['status']==status,row;return row
                time.sleep(.03)
            raise AssertionError('Import did not settle')
        try:
            assert request(exe,'ping')['capabilities']['browserTransfer'];checks+=1
            for source,payload in [('blob:https://example.com/'+uuid.uuid4().hex,bytes(range(256))*16385),('data:application/octet-stream',b''),('https://example.com/authorized-post',b'original POST response\0'*8192)]:
                key,identifier,spool,target=add(source,'received-'+uuid.uuid4().hex[:5]+'.rbxmx',payload)
                row=finished(identifier);assert row['browserTransfer'] and not row['media'];assert target.read_bytes()==payload;assert row['verified']==str(len(payload));checks+=3
                assert request(exe,'status',key=key)['state']=='committed';checks+=1
            payload=bytes(range(256))*32768
            _,identifier,_,target=add('blob:https://example.com/resume','prefix.bin',payload,payload[:1234567]);finished(identifier);assert hashlib.sha256(target.read_bytes()).digest()==hashlib.sha256(payload).digest();checks+=1
            changed_key,identifier,changed_source,target=add('blob:https://example.com/changed','changed.bin',payload,b'wrong prefix');finished(identifier,4);assert not target.exists() and pathlib.Path(str(target)+'.part').read_bytes()==b'wrong prefix';checks+=1
            command('restart '+identifier);request(exe,'browser-update',key=changed_key,file=str(changed_source),complete=True,total=str(len(payload)),received=str(len(payload)));finished(identifier);assert target.read_bytes()==payload and any(file.read_bytes()==b'wrong prefix' for file in target.parent.glob('Downshift.previous-*.part'));checks+=1
            _,identifier,_,target=add('blob:https://example.com/size','wrong-size.bin',b'correct bytes',total=999);finished(identifier,4);assert not target.exists();checks+=1
            # Preallocated/out-of-order source must not be copied before Chrome
            # reports the full response completed and its actual final size.
            key=uuid.uuid4().hex;spool=root/'receiving.source';spool.write_bytes(b'\0'*len(payload))
            entry=request(exe,'browser-prepare',key=key,url='blob:https://example.com/receiving',filename='receiving.bin',total=str(len(payload)),mime='application/octet-stream')['downloadId']
            request(exe,'commit',key=key,browserTransport=True,prompt=False)
            request(exe,'browser-update',key=key,file=str(spool),complete=False,total=str(len(payload)),received='1000000')
            time.sleep(.15);row=next(r for r in rows(p) if r['id']==entry);target=pathlib.Path(row['destination']);assert row['downloaded']=='1000000' and not pathlib.Path(str(target)+'.part').exists();checks+=1
            command('pause '+entry);assert request(exe,'browser-update',key=key,file=str(spool),complete=False,total=str(len(payload)),received='1000000')['downloadStatus']=='Paused';checks+=1
            before={r['id'] for r in rows(p)};close(p);p=start(driver,root);assert {r['id'] for r in rows(p)}==before;checks+=1
            command('resume '+entry);spool.write_bytes(payload)
            request(exe,'browser-update',key=key,file=str(spool),complete=True,total=str(len(payload)),received=str(len(payload)));finished(entry);assert target.read_bytes()==payload;checks+=1
            # Import receipts cannot be used to start the curl engine or vice versa.
            key=uuid.uuid4().hex;request(exe,'browser-prepare',key=key,url='data:application/octet-stream',filename='type.bin',total='0',mime='application/octet-stream')
            assert not host(exe,dict(version=1,command='commit',key=key,browserCancelled=True))[1]['ok'];checks+=1
            assert not host(exe,dict(version=1,command='browser-update',key=key,file='../bad',complete=True,total='0',received='0'))[1]['ok'];checks+=1
            assert not host(exe,dict(version=1,command='browser-update',key=key,file='',complete=True,total='-1'))[1]['ok'];checks+=1
            # A full received source survives cancellation/removal decisions and
            # can complete locally after restart without the browser worker.
            local_key=uuid.uuid4().hex;local_source=root/'retained.source';local_source.write_bytes(b'received data to retain')
            local_id=request(exe,'browser-prepare',key=local_key,url='blob:https://example.com/retained',filename='retained.bin',total=str(local_source.stat().st_size),mime='application/octet-stream')['downloadId']
            request(exe,'commit',key=local_key,browserTransport=True,prompt=True);request(exe,'browser-update',key=local_key,file=str(local_source),complete=True,total=str(local_source.stat().st_size),received=str(local_source.stat().st_size));command('cancel '+local_id)
            close(p);p=start(driver,root);command('resume '+local_id);retained=finished(local_id);assert pathlib.Path(retained['destination']).read_bytes()==local_source.read_bytes();checks+=1
        finally:close(p)
    print(f'Native browser transfer checks passed: {checks}')
if __name__=='__main__':main()
